import{_ as n,o as s,c as e,a2 as i}from"./chunks/framework.CBxkvBm_.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),t={name:"guide/getting-started.md"};function l(p,a,o,r,c,h){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide walks you through building your first <strong>computable digital thread</strong> in ModelScript — linking 1D dynamic physics in Modelica with 3D STEP CAD geometry and simulating the combined system.</p><hr><h2 id="_1-creating-a-workspace" tabindex="-1">1. Creating a Workspace <a class="header-anchor" href="#_1-creating-a-workspace" aria-label="Permalink to &quot;1. Creating a Workspace&quot;">​</a></h2><ol><li>Open an empty project folder in VS Code.</li><li>Run the command <code>ModelScript: Initialize Workspace</code> from the command palette (<code>Ctrl+Shift+P</code>).</li><li>This creates a standard <code>.modelscript</code> workspace index configuration.</li></ol><hr><h2 id="_2-writing-your-first-physics-model" tabindex="-1">2. Writing Your First Physics Model <a class="header-anchor" href="#_2-writing-your-first-physics-model" aria-label="Permalink to &quot;2. Writing Your First Physics Model&quot;">​</a></h2><p>Create a new file called <code>BouncingBall.mo</code>:</p><div class="language-modelica vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">modelica</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model BouncingBall</span></span>
<span class="line"><span>  parameter Real e = 0.7 &quot;Coefficient of restitution&quot;;</span></span>
<span class="line"><span>  parameter Real g = 9.81 &quot;Gravity acceleration&quot;;</span></span>
<span class="line"><span>  Real h(start=1.0) &quot;Height of ball&quot;;</span></span>
<span class="line"><span>  Real v(start=0.0) &quot;Velocity of ball&quot;;</span></span>
<span class="line"><span>equation</span></span>
<span class="line"><span>  der(h) = v;</span></span>
<span class="line"><span>  der(v) = -g;</span></span>
<span class="line"><span>  when h &lt;= 0 and v &lt; 0 then</span></span>
<span class="line"><span>    reinit(v, -e * pre(v));</span></span>
<span class="line"><span>  end when;</span></span>
<span class="line"><span>end BouncingBall;</span></span></code></pre></div><p>The native WebAssembly GLR language server instantly activates, providing sub-millisecond diagnostics, type checking, and hover info.</p><hr><h2 id="_3-weaving-the-digital-thread-binding-3d-cad" tabindex="-1">3. Weaving the Digital Thread: Binding 3D CAD <a class="header-anchor" href="#_3-weaving-the-digital-thread-binding-3d-cad" aria-label="Permalink to &quot;3. Weaving the Digital Thread: Binding 3D CAD&quot;">​</a></h2><p>In a computable digital thread, physical states directly drive geometric positions. If you have a STEP file (e.g., <code>ball.step</code>), you can bind the 3D geometry directly to the dynamic variable <code>h</code> using a <code>DynamicSelect</code> CAD annotation:</p><div class="language-modelica vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">modelica</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model BouncingBall</span></span>
<span class="line"><span>  parameter Real e = 0.7 &quot;Coefficient of restitution&quot;;</span></span>
<span class="line"><span>  parameter Real g = 9.81 &quot;Gravity acceleration&quot;;</span></span>
<span class="line"><span>  Real h(start=1.0) &quot;Height of ball&quot; annotation(</span></span>
<span class="line"><span>    CAD(</span></span>
<span class="line"><span>      shape=&quot;ball.step&quot;,</span></span>
<span class="line"><span>      transform=DynamicSelect(</span></span>
<span class="line"><span>        translate(0, 0, 0),</span></span>
<span class="line"><span>        translate(0, h, 0)</span></span>
<span class="line"><span>      )</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span>  );</span></span>
<span class="line"><span>  Real v(start=0.0) &quot;Velocity of ball&quot;;</span></span>
<span class="line"><span>equation</span></span>
<span class="line"><span>  der(h) = v;</span></span>
<span class="line"><span>  der(v) = -g;</span></span>
<span class="line"><span>  when h &lt;= 0 and v &lt; 0 then</span></span>
<span class="line"><span>    reinit(v, -e * pre(v));</span></span>
<span class="line"><span>  end when;</span></span>
<span class="line"><span>end BouncingBall;</span></span></code></pre></div><p>Open the <code>BouncingBall.mo</code> file and click the <strong>Open 3D Viewer</strong> icon in the editor toolbar to see the 3D STEP mesh animate in synchrony with the continuous physics!</p><hr><h2 id="_4-simulating-via-the-cli" tabindex="-1">4. Simulating via the CLI <a class="header-anchor" href="#_4-simulating-via-the-cli" aria-label="Permalink to &quot;4. Simulating via the CLI&quot;">​</a></h2><p>Execute the model using the unified <code>msx</code> command-line tool:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Flatten to linear DAE arena and simulate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> simulate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BouncingBall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BouncingBall.mo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stop-time</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --step-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.01</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Render the interactive SVG schematic diagram</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BouncingBall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BouncingBall.mo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schematic.svg</span></span></code></pre></div><hr><h2 id="_5-next-steps" tabindex="-1">5. Next Steps <a class="header-anchor" href="#_5-next-steps" aria-label="Permalink to &quot;5. Next Steps&quot;">​</a></h2><ul><li>Explore <a href="./../languages/overview.html">Polyglot Languages</a> to integrate SysML v2 architectural requirements and OWL2 ontologies into the digital thread.</li><li>Learn about the <a href="./../architecture/tgg.html">Triple Graph Grammar (TGG)</a> engine for automated bidirectional model synchronization.</li><li>Read about the <a href="./../architecture/theory-coordinator.html">Nelson-Oppen Coordinator</a> for cross-domain formal verification.</li></ul>`,22)])])}const u=n(t,[["render",l]]);export{g as __pageData,u as default};
